head.script:
// 담당 범위 : 정렬 제외 조건 (drilldown / expression / GroupBy / RowNum, RowStatus)
//  - 기본 동작은 _1, MultiLine 은 _3
//  - GridView sortable=true, sortEvent=onclick 고정 + 모든 Header Column 에 Column sortable=true 설정
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > sortable]<br/>Header Column 을 클릭 또는 더블 클릭하여 데이터를 정렬할지 설정합니다.",
    "validation" : [
        "Header Column 과 매칭되는 Body Column 이 inputType='drilldown','expression' 이면 정렬되지 않습니다.",
        "GridView 컴포넌트에 GroupBy 기능이 적용된 경우 정렬되지 않습니다.",
        "RowNum, RowStatus Column 은 정렬되지 않습니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (drilldown)
    con_case.setValue("drilldown");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 조직별 인원/예산 (계층 순서, depth = 계층 깊이)
//  - 조직 오름차순       : 개발센터, 경영지원본부, 본사, 연구소, 영업본부, 인사팀
//  - 인원 오름차순       : 인사팀, 경영지원본부, 본사, 연구소, 영업본부, 개발센터
//  - 1인당 예산 오름차순 : 영업본부, 인사팀, 경영지원본부, 연구소, 개발센터, 본사
scwin.rowData = [
    { "org" : "본사", "depth" : "1", "region" : "서울", "headcount" : "12", "budget" : "900" },
    { "org" : "경영지원본부", "depth" : "2", "region" : "서울", "headcount" : "7", "budget" : "300" },
    { "org" : "인사팀", "depth" : "3", "region" : "서울", "headcount" : "4", "budget" : "120" },
    { "org" : "영업본부", "depth" : "2", "region" : "부산", "headcount" : "25", "budget" : "650" },
    { "org" : "연구소", "depth" : "1", "region" : "대전", "headcount" : "18", "budget" : "820" },
    { "org" : "개발센터", "depth" : "2", "region" : "대전", "headcount" : "30", "budget" : "1500" }
];



// comp 생성
//  - 조직 Body Column : con_case = drilldown 이면 inputType=drilldown, 그 외 text (대조)
//  - 1인당 예산 Body Column : 항상 inputType=expression
//  - 인원 Body Column : 항상 text (정렬 동작 대조 Column)
//  - con_case = groupby 이면 생성 후 지역 Column 기준 groupby 적용
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] GridView sortable=true, sortEvent=onclick, 모든 Header Column 에 sortable=true\n[전제] 1인당 예산 Column 은 항상 expression, 인원 Column 은 항상 text (정렬 대조)\n[절차] 조건 선택 -> Target 재생성 -> Header 1개 클릭 -> 정렬 상태 확인 (Header 마다 반복)\n[확인] 정렬 상태와 조직 표시 순서"', '', 'label1');

    // 조건 설정
    let cCase = con_case.getValue();

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 dataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="org" name="org" dataType="text"></w2:column>';
    strDlt += '<w2:column id="depth" name="depth" dataType="text"></w2:column>';
    strDlt += '<w2:column id="region" name="region" dataType="text"></w2:column>';
    strDlt += '<w2:column id="headcount" name="headcount" dataType="number"></w2:column>';
    strDlt += '<w2:column id="budget" name="budget" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON(scwin.rowData, false);

    // 조직 Body Column inputType
    let attrOrg = (cCase === "drilldown") ? ' inputType="drilldown" depthColumn="depth"' : ' inputType="text"';

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" sortable="true" sortEvent="onclick" rowNumVisible="true" rowNumHeaderValue="순번" rowStatusVisible="true" rowStatusHeaderValue="상태" style="width:640px;height:290px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="column_org" value="조직" sortable="true"></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="column_region" value="지역" sortable="true"></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="column_headcount" value="인원" sortable="true"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column_budget" value="예산" sortable="true"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column_perHead" value="1인당 예산" sortable="true"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="150" style="text-align:left;" id="org" value=""' + attrOrg + '></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="region" value=""></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="headcount" value="" dataType="number"></w2:column>';
    strTarget += '<w2:column width="90" style="" inputType="text" id="budget" value="" dataType="number"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="expression" id="perHead" dataType="number" displayFormat="#,##0.0" expression="Number(display(\'budget\'))/Number(display(\'headcount\'))"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // GroupBy 적용 (지역 Column 기준)
    if (cCase === "groupby" && scwin["target1"]) {
        target1.groupby({ sortIndex : [1], sortOrder : [1] });
    }
}



// validation 1, 2, 3 판정 출력 : 정렬 상태 + 조직 표시 순서
scwin.btn_checkSort_onclick = function (e) {
    let arrStatus = target1.getSortableStatus() || [];
    let strSort = (arrStatus.length === 0) ? "없음" : arrStatus.map(function (o) {
        return o.colID + " (" + (o.sortOrder == 1 ? "오름차순" : "내림차순") + ")";
    }).join(", ");

    // 조직 표시 순서 : GroupBy 는 Group Header/Footer Row 가 끼므로 DataList(그룹 순서로 재배치됨) 기준,
    //                  그 외는 GridView 표시 순서 기준 (drilldown 은 정렬 시 DataList 순서가 바뀌지 않음)
    let isGroupby = (con_case.getValue() === "groupby");
    let arrOrg = [];
    for (let i = 0; i < dlt_bind.getRowCount(); i++) {
        arrOrg.push(isGroupby ? dlt_bind.getCellData(i, "org") : target1.getCellDisplayData(i, "org"));
    }

    wf_body_bottom.getObj("scwin").setReturnValue("정렬 상태 : " + strSort + " / 조직 표시 순서 : " + arrOrg.join(", "));
}
